262	        assertThrows(ConflictException.class, () -> service.accept(tampered));
263	        JobResponse current = service.getJob(first.id());
264	        assertEquals(first.trainNo(), current.trainNo());
265	        assertEquals(1, jdbc.queryForObject("SELECT COUNT(*) FROM train_job", Integer.class));
266	    }
