270	        JobResponse job = acceptAndCheck("k11", "G12", 10, 0);
271	        service.brakeTest(job.id(), sensitivity("k11-s", 50, 500, true));
272	        service.brakeTest(job.id(), stability("k11-t", 140, 500, false));
273	        service.confirmDeparture(job.id(), new RequestIdOnly("k11-d"));
274	
275	        ClosureResponse closed = service.close(job.id(), new RequestIdOnly("k11-x"));
276	        assertTrue(closed.closed());
277	        assertFalse(closed.repeated());
278	        assertEquals("CLOSED", service.getJob(job.id()).status());
279	
280	        // 重复销记（新幂等键）：幂等成功
281	        ClosureResponse repeated = service.close(job.id(), new RequestIdOnly("k11-x2"));
282	        assertTrue(repeated.closed());
283	        assertTrue(repeated.repeated());
