2	
3	import org.springframework.dao.DuplicateKeyException;
4	import org.springframework.jdbc.core.JdbcTemplate;
5	import org.springframework.stereotype.Repository;
6	
7	import java.util.Optional;
8	
9	/**
10	 * 幂等记录数据访问；request_id 主键保证同键唯一。
11	 */
12	@Repository
13	public class IdempotencyRepository {
14	
15	    /**
16	     * 幂等记录行。
17	     *
18	     * @param requestId    幂等请求键
19	     * @param operation    操作类型
20	     * @param fingerprint  请求指纹 SHA-256
21	     * @param responseBody 首次成功响应 JSON 快照
22	     */
23	    public record IdempotencyRow(String requestId, String operation, String fingerprint, String responseBody) {
24	    }
25	
26	    private final JdbcTemplate jdbc;
27	
28	    public IdempotencyRepository(JdbcTemplate jdbc) {
29	        this.jdbc = jdbc;
30	    }
31	
32	    /**
33	     * 按键查询幂等记录。
34	     */
35	    public Optional<IdempotencyRow> findByRequestId(String requestId) {
36	        return jdbc.query("SELECT request_id, operation, fingerprint, response_body"
37	                        + " FROM idempotency_record WHERE request_id = ?",
38	                (rs, n) -> new IdempotencyRow(rs.getString("request_id"), rs.getString("operation"),
39	                        rs.getString("fingerprint"), rs.getString("response_body")),
40	                requestId).stream().findFirst();
41	    }
42	
43	    /**
44	     * 写入幂等记录；同键并发写入时仅一条成功。
45	     *
46	     * @throws DuplicateKeyException 同键已存在
47	     */
48	    public void insert(String requestId, String operation, String fingerprint, String responseBody) {
49	        jdbc.update("INSERT INTO idempotency_record (request_id, operation, fingerprint, response_body, created_at)"
50	                + " VALUES (?, ?, ?, ?, CURRENT_TIMESTAMP)", requestId, operation, fingerprint, responseBody);
51	    }
52	
53	    /**
54	     * 更新响应快照（同事务内先占键后写快照）。
