29	        this.jdbc = jdbc;
30	    }
31	
32	    /**
33	     * 追加车辆，顺位为指定起始值。
34	     */
35	    public void insert(long jobId, int seqNo, CarDto car) {
36	        jdbc.update("INSERT INTO train_car (job_id, car_no, seq_no, weight_tons, length, valve_closed,"
37	                        + " detached, created_at) VALUES (?, ?, ?, ?, ?, ?, FALSE, CURRENT_TIMESTAMP)",
38	                jobId, car.carNo(), seqNo, car.weightTons(), car.length(), car.valveClosed());
39	    }
