42	     * 查询在列车辆（未摘下），按顺位排序。
43	     */
44	    public List<CarRow> findActiveByJobId(long jobId) {
45	        return jdbc.query("SELECT * FROM train_car WHERE job_id = ? AND detached = FALSE ORDER BY seq_no, id",
46	                ROW_MAPPER, jobId);
