51	     */
52	    public boolean detach(long jobId, String carNo) {
53	        return jdbc.update("UPDATE train_car SET detached = TRUE"
54	                + " WHERE job_id = ? AND car_no = ? AND detached = FALSE", jobId, carNo) > 0;
55	    }
